      "directives": [
        {
          "sourceLine": 140,
          "text": "【可选查看：货单／航线／归船安排。三项可重复阅读，不改变状态。必须看见一次航线成本与终点停泊说明；无需逐句点击所有闲谈才能离开。】"
        },
        {
          "sourceLine": 142,
          "text": "【场景退出：固定货单确认；本夜任务终点与次晨归还约定已成立。】"
        }
      ],
      "backdropAssetId": "C_ENV_M01:dusk-loaded-front",
